请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-008

=== 用户原始指令 (query.txt) ===
帮我整个按钮,点一下能跳到番茄钟app吧

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个按钮,点一下能跳到番茄钟app吧",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "focus": {
      "badge": {
        "type": "string",
        "description": "专注入口的短状态标签。",
        "sampleValue": "专注模式"
      },
      "title": {
        "type": "string",
        "description": "卡片主标题，说明入口面向番茄钟专注计时。",
        "sampleValue": "番茄钟专注"
      },
      "subtitle": {
        "type": "string",
        "description": "卡片主说明，提示用户可进入专注计时。",
        "sampleValue": "一键进入专注计时"
      },
      "hint": {
        "type": "string",
        "description": "按钮旁的轻量辅助提示。",
        "sampleValue": "轻触按钮打开专注入口"
      },
      "actionLabel": {
        "type": "string",
        "description": "跳转按钮上显示的短文案。",
        "sampleValue": "去番茄钟"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式图标，适合用于番茄钟或专注入口的视觉识别。"
    }
  ]
}

